properties.query:
let GraphPreConsent = externaldata(Name:string, Client_Id:string, Enabled:string, Graph_api_permissions:string, 
Auth_code:string, Device_code:string, Brk_refresh:string, Foci:string, Reply_addresses:string)
[h'https://raw.githubusercontent.com/SlimKQL/Hunting-Queries-Detection-Rules/refs/heads/main/IOC/GraphPreConsent.csv'];
//let SafeApps = dynamic(["contoso-helpdesk", "microsoft-teams", "outlook-service"]);
//let TrustedApps = dynamic(["00000003-0000-0000-c000-000000000000"]);
MicrosoftGraphActivityLogs
| where TimeGenerated > ago(7d)
| where RequestMethod  has_any ("POST", "PATCH", "PUT", "DELETE")
| where ResponseStatusCode in ("200" , "201" , "203", "204" , "205" , "206") //For Succesful status codes
| join kind=innerunique GraphPreConsent on $left.AppId == $right.Client_Id
//| where AppId !in (TrustedApps) and Name !in (SafeApps)
| summarize ActivityCount = count(), Users = make_set(UserId, 10) //, Permissions = make_set(Graph_api_permissions, 5)
  by AppId, Name, IPAddress, Client_Id, RequestMethod, RequestUri
| where ActivityCount > 5
